//! R035/18 — Debugger trusted monotonic trace ring.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Frame{pub sequence:u64,pub pc:u64}pub struct Trace<const N:usize>{owner:u64,frames:[Option<Frame>;N],count:usize,last:u64}impl<const N:usize> Trace<N>{pub fn new(owner:u64)->Self{Self{owner,frames:[None;N],count:0,last:0}}pub fn record(&mut self,owner:u64,trusted:bool,frame:Frame)->Result<(),Error>{if owner==0||owner!=self.owner||!trusted{return Err(Error::Denied);}if frame.sequence<=self.last||frame.pc==0{return Err(Error::Stale);}if N==0{return Err(Error::Full);}if self.count==N{for i in 1..N{self.frames[i-1]=self.frames[i];}self.count-=1;}self.frames[self.count]=Some(frame);self.count+=1;self.last=frame.sequence;Ok(())}pub fn latest(&self)->Option<Frame>{if self.count==0{None}else{self.frames[self.count-1]}}}
#[cfg(test)]mod tests{use super::*;#[test]fn real_workflow_and_failure_guard(){let mut t=Trace::<2>::new(7);t.record(7,true,Frame{sequence:1,pc:4}).unwrap();t.record(7,true,Frame{sequence:2,pc:8}).unwrap();t.record(7,true,Frame{sequence:3,pc:9}).unwrap();assert_eq!(t.latest(),Some(Frame{sequence:3,pc:9}));}}
